use std::{env,path::PathBuf,process::Command};
fn main(){let out=PathBuf::from(env::var("OUT_DIR").unwrap());let mut objects=Vec::new();for stem in ["simd8","simd8_fast"]{let obj=out.join(format!("{stem}.o"));assert!(Command::new("gcc").args(["-O3","-march=native","-std=c11","-fPIC","-Wall","-Wextra","-c"]).arg(format!("{stem}.c")).arg("-o").arg(&obj).status().unwrap().success());objects.push(obj);println!("cargo:rerun-if-changed={stem}.c");}assert!(Command::new("ar").arg("crs").arg(out.join("libsimd8.a")).args(objects).status().unwrap().success());println!("cargo:rustc-link-search=native={}",out.display());println!("cargo:rustc-link-lib=static=simd8");println!("cargo:rustc-link-search=native=/home/hclau/ecdsa_research/shake8-20261015");println!("cargo:rustc-link-lib=dylib=shake8");println!("cargo:rustc-link-arg=-Wl,-rpath,/home/hclau/ecdsa_research/shake8-20261015");println!("cargo:rerun-if-changed=simd8.h");}
